import{_ as d,C as a,c as p,o as l,j as o,G as s,ak as c,a as r}from"./chunks/framework.D7ejh1zC.js";const C=JSON.parse('{"title":"大小写规则检测","description":"","frontmatter":{},"headers":[],"relativePath":"module/git/大小写规则检测.md","filePath":"concept/module/git/大小写规则检测.md","lastUpdated":1786880804000}'),_={name:"module/git/大小写规则检测.md"};function h(m,e,u,g,k,b){const t=a("mdInfo"),i=a("NolebaseGitContributors"),n=a("NolebaseGitChangelog");return l(),p("div",null,[e[0]||(e[0]=o("h1",{id:"大小写规则检测",tabindex:"-1"},[r("大小写规则检测 "),o("a",{class:"header-anchor",href:"#大小写规则检测","aria-label":'Permalink to "大小写规则检测"'},"​")],-1)),s(t),e[1]||(e[1]=c('<p>在 Git 中有一个虽然很小但很致命的问题：他对英文字母大小写检测默认是忽略的。这会造成什么后果呢？</p><p>​ 我们来看一个场景：同事 A 新建了一个文件夹 <code>components</code> ，在其中创建一个组件 <code>Upload.vue</code> ，其他页面都是以 <code>xxx/Upload.vue</code> 为路径。后面修改为小写字母 <code>upload.vue</code> ，而文件路径也做相应的修改。 ​ 本地环境运行没有问题，但是推送到远程服务器时由于 Git 忽略大小写，因此远程服务器还是 <code>Upload.vue</code> 文件，则路径找不到 <code>upload.vue</code> 文件开始报错。</p><p>解决方法很简单，把忽略大小写的规则禁用即可，命令如下：</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core.ignorecase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>禁用之后可以发现能够检测到文件的变化并提交远程了。</p>',5)),s(i),s(n)])}const f=d(_,[["render",h]]);export{C as __pageData,f as default};
